// Save creates the MenuItemVariant entities in the database.
func (mivcb *MenuItemVariantCreateBulk) Save(ctx context.Context) ([]*MenuItemVariant, error) {
	if mivcb.err != nil {
		return nil, mivcb.err
	}
	specs := make([]*sqlgraph.CreateSpec, len(mivcb.builders))
	nodes := make([]*MenuItemVariant, len(mivcb.builders))
	mutators := make([]Mutator, len(mivcb.builders))
	for i := range mivcb.builders {
		func(i int, root context.Context) {
			builder := mivcb.builders[i]
			builder.defaults()
			var mut Mutator = MutateFunc(func(ctx context.Context, m Mutation) (Value, error) {
				mutation, ok := m.(*MenuItemVariantMutation)
				if !ok {
					return nil, fmt.Errorf("unexpected mutation type %T", m)
				}
				if err := builder.check(); err != nil {
					return nil, err
				}
				builder.mutation = mutation
				var err error
				nodes[i], specs[i] = builder.createSpec()
				if i < len(mutators)-1 {
					_, err = mutators[i+1].Mutate(root, mivcb.builders[i+1].mutation)
				} else {
					spec := &sqlgraph.BatchCreateSpec{Nodes: specs}
					spec.OnConflict = mivcb.conflict
					// Invoke the actual operation on the latest mutation in the chain.
					if err = sqlgraph.BatchCreate(ctx, mivcb.driver, spec); err != nil {
						if sqlgraph.IsConstraintError(err) {
							err = &ConstraintError{msg: err.Error(), wrap: err}
						}
					}
				}
				if err != nil {
					return nil, err
				}
				mutation.id = &nodes[i].ID
				mutation.done = true
				return nodes[i], nil
			})
			for i := len(builder.hooks) - 1; i >= 0; i-- {
				mut = builder.hooks[i](mut)
			}
			mutators[i] = mut
		}(i, ctx)
	}
	if len(mutators) > 0 {
		if _, err := mutators[0].Mutate(ctx, mivcb.builders[0].mutation); err != nil {
			return nil, err
		}
	}
	return nodes, nil
}

